import React from 'react';
import { ShootDetailsSection, ReelsSection, PhotosSection } from './PrintableSections';

/**
 * Read-only, printable view of Shoot Details / Reels / Photos -- reuses the
 * exact same sections (and `rr-review-*` styling) as Review & Approval, and
 * the same window.print() flow, so printed output looks and behaves
 * identically to what "Preview Printable Version" already produces there.
 */
export default function StepPrintDetails({ plan, goToStep }) {
  return (
    <>
      <div className="rr-wiz-step-title">Print Details</div>
      <div style={{ fontSize: 13, color: 'rgba(0,0,0,.55)', marginBottom: 20 }}>
        A printable summary of Shoot Details, Reels, and Photos — pulled straight from those steps.
      </div>

      <ShootDetailsSection plan={plan} />
      <ReelsSection plan={plan} goToStep={goToStep} />
      <PhotosSection plan={plan} goToStep={goToStep} />

      <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
        <button type="button" className="rr-toggle-btn" onClick={() => window.print()}>
          Preview Printable Version
        </button>
      </div>
    </>
  );
}
